const gridData = options.tgvContext.getGridData();
let focusedCell;
if (gridData.focus && gridData.focus.length) {
	focusedCell = gridData.focus[0];
}

const dataObjectString =
	focusedCell && (focusedCell.cell.data || focusedCell.row.cells[0].data);

let dataObject;
if (dataObjectString) {
	try {
		dataObject = JSON.parse(dataObjectString);
	} catch {
		dataObject = null;
	}
}

const selectedRowIds = options.getState().grid.selectedRows;
const defaultInvalidIdValueInTemplate = 'INVALID_ID_VALUE';
const disabled =
	selectedRowIds.length > 1 ||
	!dataObject ||
	!dataObject.id ||
	!dataObject.type ||
	dataObject.id === defaultInvalidIdValueInTemplate;
return { disabled };
